 for(const [id,route,msg] of [['recoveryRequest','request','recoveryMsg'],['recoveryRedeem','redeem','redeemMsg']]){const f=authBody.querySelector('#'+id);f.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f)),out=authBody.querySelector('#'+msg),btn=f.querySelector('button');btn.disabled=true;try{if(route==='redeem'&&b.password!==b.confirmation)throw Error('Les mots de passe ne correspondent pas');await api('recovery/'+route,b);out.textContent=route==='request'?'Si ce compte existe, la demande sera traitée par le Super Admin.':'Mot de passe modifié. Retournez à la connexion.';if(route==='redeem')f.reset()}catch(err){out.textContent=err.message}finally{btn.disabled=false}}}
