 if(section==='parametres'){const d=clientState.profile;show(title+`<div class="client-settings"><form id="profileForm" class="card client-form"><h2>Mon profil</h2><label>Adresse e-mail<input readonly value="${esc(clientState.email)}"></label>${filledField('name','Nom et prénom',d.name)}${filledField('phone','Téléphone',d.phone,'tel')}<button>Enregistrer mon profil</button></form><form id="passwordForm" class="card client-form"><h2>Modification du mot de passe</h2><label>Mot de passe actuel<input type="password" name="current" autocomplete="current-password" required></label><label>Nouveau mot de passe<input type="password" name="password" autocomplete="new-password" minlength="10" required></label><label>Confirmer le nouveau mot de passe<input type="password" name="confirmation" autocomplete="new-password" minlength="10" required></label><button>Modifier le mot de passe</button></form></div>`);form(async b=>{await clientUpdate({...b,kind:'profile'});document.querySelector('#msg').textContent='Profil enregistré.'});document.querySelector('#passwordForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));try{if(b.password!==b.confirmation)throw Error('Les mots de passe ne correspondent pas.');await api('password',b);location.replace('/client/connexion')}catch(e){error(e)}};return}
