 show(`<div class="catalog-head"><div><span class="eyebrow">SUPER ADMIN</span><h1>Gestion des boutiques</h1></div><button id="adminRefresh">Actualiser</button></div><div class="admin-stats">${[['Boutiques',d.shops.length],['Actives',d.shops.filter(x=>state(x)==='Active').length],['Expirées',d.shops.filter(x=>state(x)==='Expirée').length],['Demandes en attente',pending.length]].map(([k,v])=>`<div class="card"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><section class="card admin-panel"><div class="admin-filters"><input id="adminSearch" placeholder="Rechercher une boutique ou un e-mail"><select id="adminStatus"><option value="">Tous les statuts</option>${['Active','Expirée','Suspendue','Archivée'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Entreprise</th><th>Plan</th><th>Expiration</th><th>Statut</th><th>Actions</th></tr></thead><tbody id="adminRows"></tbody></table></div></section><section class="card admin-panel"><h2>Demandes de paiement</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Boutique</th><th>Plan</th><th>Référence</th><th>Statut</th><th>Actions</th></tr></thead><tbody>${d.requests.map(x=>`<tr><td>${esc(d.shops.find(y=>y.id===x.shop)?.name||x.shop)}</td><td>${esc(x.plan)}</td><td>${esc(x.reference)}</td><td>${esc(x.status)}</td><td>${x.status==='pending'?`<button data-request="${esc(x.id)}" data-decision="approve">Valider</button> <button data-request="${esc(x.id)}" data-decision="reject" class="admin-danger">Rejeter</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="5">Aucune demande</td></tr>'}</tbody></table></div></section><section class="card admin-panel"><details><summary>Journal d’audit récent</summary>${d.audit.map(x=>`<p>${new Date(x.created).toLocaleString('fr-FR')} · ${esc(x.action)} · ${esc(d.shops.find(y=>y.id===x.shop)?.name||'Plateforme')}</p>`).join('')}</details></section>`);
 const act=async(button,route,payload,question)=>{if(question&&!await dbConfirm(question))return;button.disabled=true;try{await api('admin/'+route,payload);await renderSuperAdmin()}catch(e){alert(e.message);button.disabled=false}};
