function shuffleCatalog(items){const result=items.slice();for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
async function run(){try{me=await api('me')}catch(e){me=null}if(me?.role==='ADMIN'||me?.role==='SUPER_ADMIN'){professionalNav();if(authPaths.has(path)||path.startsWith('/client/')){if(authModal.open)authModal.close();location.replace(me.role==='ADMIN'?'/gestion/dashboard':'/superadmin/dashboard');return}}if(path.startsWith('/client/')&&!authPaths.has(path)){if(!await clientSession()){show('<h1>Espace client</h1><p>Connectez-vous pour accéder à vos achats.</p>');openAuth('/client/connexion');return}await renderClient();return}if(!path.startsWith('/superadmin/')&&path!=='/espace'&&await clientSession())clientNav();if(path==='/abonnements'){show('<h1>Nos offres</h1>'+pricing());return}if(path==='/espace'||path.startsWith('/superadmin/')){try{me=await api('me')}catch{location.href='/connexion';return}if(me.force){show(`<h1>Modifier le mot de passe initial</h1><form>${field('password','Nouveau mot de passe','password')}<button>Enregistrer</button></form>`);form(async b=>{await api('password',b);location.href='/connexion'});return}if(me.role==='SUPER_ADMIN'){await renderSuperAdmin();return}else if(me.role==='ADMIN'){location.replace('/gestion/dashboard');return}else {location.replace('/client/panier');return}const b=document.createElement('button');b.textContent='Déconnexion';b.onclick=async()=>{await api('logout',{});location.href='/'};main.append(b);return}if(authPaths.has(path)&&!me)openAuth(path);const list=shuffleCatalog(await api('catalog'));if(path.startsWith('/produit/')||path.startsWith('/service/')){const x=list.find(x=>x.id===decodeURIComponent(path.split('/')[2]));if(!x){show('<h1>Article indisponible</h1>');return}const service=String(x.type).toLowerCase()==='service',available=service||Number(x.stock)>0,wa=(x.phone||'').replace(/\D/g,''),detailPriceLabel=service?'Tarif':'Prix de vente';show(`<section class="detail-page"><div class="detail-breadcrumb">Accueil / Catalogue / ${service?'Service':'Produit'}</div><div class="detail-shell"><article class="detail-media-card"><div class="detail-media">${x.image?`<img loading="eager" decoding="async" src="${esc(x.image)}" alt="${esc(x.name)}">`:`<div class="detail-placeholder">DB</div>`}<span class="detail-tag">${service?'Service':'Produit'}</span></div></article><article class="detail-panel"><div class="detail-topline"><span class="detail-category">${esc(x.category||'Catalogue')}</span><span class="detail-availability ${available?'':'unavailable'}">${service?'Sur demande':available?'Disponible en stock':'Rupture de stock'}</span></div><h1 class="detail-title">${esc(x.name)}</h1><a class="detail-shoplink" href="/boutique/${encodeURIComponent(x.shop)}">${esc(x.shop_name)} · ${esc(x.location)}</a><p class="detail-description">${esc(x.description||'Aucune description fournie pour cette offre.')}</p><div class="detail-pricebox"><div class="detail-price-wrap"><span class="label">${detailPriceLabel}</span><div class="detail-price-value">${money(x.price)}</div>${x.serviceFee>0?`<div class="detail-fee">Frais de service inclus : <strong>${money(x.serviceFee)}</strong></div>`:''}</div><div class="detail-note"><strong>${service?'Prestation de service':'Commande boutique'}</strong><br>${service?'Cette prestation est proposée sur demande. La boutique vous contactera pour la prise en charge.':'Ajoutez ce produit au panier pour préparer votre commande en ligne.'}</div></div><div class="detail-meta"><div class="detail-meta-card"><small>Type</small><strong>${service?'Service':'Produit'}</strong></div><div class="detail-meta-card"><small>${service?'Disponibilité':'Stock disponible'}</small><strong>${service?'Sur demande':money(Number(x.stock)||0).replace(' F CFA','')+' unité(s)'}</strong></div><div class="detail-meta-card"><small>Boutique</small><strong>${esc(x.shop_name)}</strong></div><div class="detail-meta-card"><small>Localisation</small><strong>${esc(x.location||'Non précisée')}</strong></div></div><div class="detail-actions"><button class="primary wide" data-add-cart="${esc(x.id)}" ${available?'':'disabled'}>${service?'Commander ce service':'Ajouter au panier'}</button><button class="secondary" data-favorite="${esc(x.id)}">${clientState?.favorites.includes(x.id)?'♥ Favori':'♡ Favori'}</button>${wa?`<a class="ghost" target="_blank" rel="noopener" href="https://wa.me/${wa}?text=${encodeURIComponent('Bonjour '+x.shop_name+', je souhaite avoir plus de détails sur '+x.name+' : '+location.href)}">Contacter la boutique</a>`:''}<a class="secondary" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(x.name+' — '+location.href)}">Partager</a></div></article></div><section class="detail-extra"><h2>Détails de l’offre</h2><div class="detail-info-grid"><div class="detail-meta-card"><small>Catégorie</small><strong>${esc(x.category||'Catalogue général')}</strong></div><div class="detail-meta-card"><small>Référence boutique</small><strong>${esc(x.id)}</strong></div><div class="detail-meta-card"><small>Mode d’achat</small><strong>${service?'Commande de prestation':'Achat direct via panier'}</strong></div></div><div class="detail-note"><strong>Conseil :</strong> utilisez le bouton <em>${service?'Commander ce service':'Ajouter au panier'}</em> pour préparer votre achat, ou contactez directement la boutique pour des informations complémentaires.</div></section></section>`);return}if(path==='/boutiques'){show('<h1>Nos boutiques</h1><div class="grid">'+[...new Map(list.map(x=>[x.shop,x])).values()].map(x=>`<a class="card" href="/boutique/${x.shop}">${esc(x.shop_name)} · ${esc(x.location)}</a>`).join('')+'</div>');return}show(`<div class="catalog-tools"><div class="filters"><input id="search" placeholder="Rechercher un article ou une boutique…" aria-label="Recherche"><select id="category" aria-label="Catégorie"><option value="">Toutes catégories</option>${[...new Set(list.map(x=>x.category).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="shopFilter" aria-label="Boutique"><option value="">Toutes boutiques</option>${[...new Map(list.map(x=>[x.shop,x.shop_name])).entries()].map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('')}</select><select id="typeFilter" aria-label="Type"><option value="">Tous types</option><option value="produit">Produits</option><option value="service">Services</option></select><input id="max" type="number" min="0" placeholder="Prix maximum" aria-label="Prix maximum"><button id="resetFilters" type="button">Réinitialiser</button></div></div><div class="grid" id="items"></div><div class="pagination"><button id="prev">Précédent</button><span id="page"></span><button id="next">Suivant</button></div>`);let page=0;function render(){const a=list.filter(x=>(!document.querySelector('#shopFilter').value||x.shop===document.querySelector('#shopFilter').value)&&(!document.querySelector('#typeFilter').value||String(x.type).toLowerCase()===document.querySelector('#typeFilter').value)&&(!['/produits','/services'].includes(path)||String(x.type).toLowerCase()===path.slice(1,-1))&&(!path.startsWith('/boutique/')||x.shop===path.split('/')[2])&&[x.name,x.shop_name,x.description].join(' ').toLowerCase().includes(document.querySelector('#search').value.toLowerCase())&&(!document.querySelector('#category').value||x.category===document.querySelector('#category').value)&&(!document.querySelector('#max').value||x.price<=Number(document.querySelector('#max').value)));page=Math.max(0,Math.min(page,Math.ceil(a.length/16)-1));document.querySelector('#items').innerHTML=a.slice(page*16,page*16+16).map(card).join('')||'<div class="empty-catalog"><h2>Aucune offre trouvée</h2><p>Modifiez vos filtres ou revenez lorsque de nouveaux articles seront publiés.</p></div>';document.querySelector('#prev').disabled=page===0;document.querySelector('#next').disabled=(page+1)*16>=a.length;document.querySelector('#page').textContent=`${page+1} / ${Math.max(1,Math.ceil(a.length/16))}`;document.querySelector('.pagination').hidden=a.length<=16}document.querySelector('#resetFilters').onclick=()=>{main.querySelectorAll('.filters input,.filters select').forEach(x=>x.value='');page=0;render()};main.querySelectorAll('input,select').forEach(x=>x.oninput=()=>{page=0;render()});document.querySelector('#prev').onclick=()=>{page--;render()};document.querySelector('#next').onclick=()=>{page++;render()};render()}

window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()});
run().catch(e=>{show('<p role="alert">'+esc(e.message)+'</p>')});
